from jsonb_to_recordset('[{"id": "hankook-634046", "url": "https://www.hankooktire.com/kr/ko/company/media-list/media-detail.634046.html", "title": "한국타이어, 폭스바겐 ‘ID.폴로·ID.크로스’에 아이온 공급해 EV 파트너십 강화", "category": "공급 / 계약", "date": "2026-10-21", "topics": ["전기차 / 저회전저항", "겨울용 / 올웨더", "타이어 설계 / 성능"], "tags": ["아이온 에보", "아이온 아이셉트", "V자형 트레드", "전용 컴파운드"], "summary": "폭스바겐 소형 전기차용 아이온의 여름·겨울 설계를 설명한다. 겨울용 제품은 V자형 패턴과 전용 고무 배합으로 눈길 구동·제동에 대응한다.", "study": "공부 질문: 전기차의 하중·순간 토크 요구와 겨울철 접지 요구를 패턴과 재료 설계로 어떻게 함께 만족시킬까?"}, {"id": "hankook-634039", "url": "https://www.hankooktire.com/kr/ko/company/media-list/media-detail.634039.html", "title": "한국타이어, 대형 카고 후륜용 타이어 ‘스마트플렉스 DH51’ 신규 규격 출시", "category": "상용차 / 내구성", "date": "2026-10-19", "topics": ["타이어 설계 / 성능", "소음 / 진동"], "tags": ["스마트플렉스 DH51", "3D 사이프", "히든 그루브", "비드 구조"], "summary": "대형 카고 후륜 타이어의 새 규격과 설계 요소를 소개한다. 3D 사이프, 마모 후 드러나는 홈, 비드 보강을 통해 수명·빗길 성능·내구성을 함께 고려한다.", "study": "공부 질문: 구동축 타이어에서 견인력, 균일 마모, 소음과 비드 내구성의 설계 우선순위는 어떻게 달라질까?"}, {"id": "hankook-633936", "url": "https://www.hankooktire.com/kr/ko/company/media-list/media-detail.633936.html", "title": "한국타이어, ‘2026 IDEA 디자인 어워드’ 본상 2관왕", "category": "미래 모빌리티 / 비공기입", "date": "2026-09-30", "topics": ["공정 / 자원순환", "컴파운드 / 재료"], "tags": ["휠봇2", "3축 구동", "블래더", "업사이클링"], "summary": "구형 바퀴를 이용하는 휠봇2와 생산 부산물인 블래더를 재활용한 디자인 사례를 다룬다. 휠봇2의 전 방향 이동과 블래더 분말의 제품화가 구체적인 기술 주제다.", "study": "공부 질문: 구형 휠의 구동·조향 자유도와 생산 부산물의 물성·가공성을 각각 어떤 시험으로 확인해야 할까?"}, {"id": "hankook-633925", "url": "https://www.hankooktire.com/kr/ko/company/media-list/media-detail.633925.html", "title": "한국타이어, 미국 ‘레이싱 아메리카’에 레이싱 타이어 독점 공급 및 후원", "category": "공급 / 계약", "date": "2026-09-29", "topics": [], "tags": ["레이싱 아메리카", "2027~2031", "기술 지원", "레이싱 타이어"], "summary": "레이싱 아메리카 주요 네 대회에 2027년부터 2031년까지 타이어와 기술 지원을 제공하는 계약을 소개한다. 신규 공급과 기존 파트너십 갱신을 함께 다룬다.", "study": "공부 질문: 여러 대회에 동일 공급사가 참여할 때 규격·수요 예측·현장 기술 지원·품질 대응 범위를 계약에서 어떻게 정할까?"}, {"id": "hankook-633919", "url": "https://www.hankooktire.com/kr/ko/company/media-list/media-detail.633919.html", "title": "한국타이어, 폭스바겐 ‘아틀라스’ OE 공급…북미 SUV 포트폴리오 확대", "category": "공급 / 계약", "date": "2026-09-28", "topics": ["타이어 설계 / 성능", "소음 / 진동", "컴파운드 / 재료"], "tags": ["다이나프로 HPX", "3D 그립컨트롤 사이프", "널링", "멀티 피치"], "summary": "아틀라스용 타이어의 맞물림 사이프와 넓은 접지면 설계를 설명한다. 고무 배합은 마모 성능에, 홈 내부 널링과 피치 배열은 소음 저감에 연결된다.", "study": "공부 질문: 블록의 움직임을 억제하면서 접지력을 유지하는 방법과 피치 배열이 소음을 바꾸는 원리를 정리해보자."}, {"id": "hankook-633895", "url": "https://www.hankooktire.com/kr/ko/company/media-list/media-detail.633895.html", "title": "한국타이어, 유럽 트레일러 제조사 ‘슈미츠 카고불’과 OE 파트너십 체결", "category": "공급 / 계약", "date": "2026-09-18", "topics": ["상용차 / 내구성"], "tags": ["슈미츠 카고불", "상용차 OE", "공급 연장", "스마텍"], "summary": "슈미츠 카고불과 상용 타이어 공급을 2030년 6월까지 연장한 계약이다. 사용 목적이 다른 상용 타이어 제품과 품질·수명 요구를 함께 소개한다.", "study": "공부 질문: 장기 공급에서 고객 승인 규격, 설계 변경, 생산 거점과 공급 중단 위험을 어떻게 관리할까?"}, {"id": "hankook-633892", "url": "https://www.hankooktire.com/kr/ko/company/media-list/media-detail.633892.html", "title": "한국타이어, ‘벨기에 랠리 챔피언십’ 공식 타이어 공급사 선정", "category": "공급 / 계약", "date": "2026-09-17", "topics": [], "tags": ["BRC", "2027~2029", "랠리 타이어", "독점 공급"], "summary": "벨기에 랠리 챔피언십의 세 클래스에 2027년부터 2029년까지 레이싱 타이어를 공급하는 계약을 소개한다.", "study": "공부 질문: 대회별 사용 규정과 타이어 규격, 현장 재고·교체 수요를 공급 계획에 어떻게 반영할까?"}, {"id": "hankook-633874", "url": "https://www.hankooktire.com/kr/ko/company/media-list/media-detail.633874.html", "title": "한국타이어, 현대 ‘아반떼’ 신차용 타이어 공급으로 전략적 파트너십 강화", "category": "공급 / 계약", "date": "2026-09-15", "topics": ["타이어 설계 / 성능", "소음 / 진동", "겨울용 / 올웨더"], "tags": ["키너지 XP", "프로파일", "숄더 그루브", "피치 시퀀싱"], "summary": "아반떼용 키너지 XP의 사계절 접지·마모·정숙성 설계를 소개한다. 고무 배합과 프로파일, 사이프·숄더 홈, 널링·피치 배열의 역할을 구분할 수 있다.", "study": "공부 질문: 눈길 성능을 위한 홈 설계와 정숙성·균일 마모를 위한 형상 설계는 어떤 상충 관계가 있을까?"}, {"id": "hankook-633829", "url": "https://www.hankooktire.com/kr/ko/company/media-list/media-detail.633829.html", "title": "한국타이어, 금산공장에 자가소비형 태양광 발전설비 신규 구축", "category": "환경 / 에너지", "date": "2026-09-03", "topics": ["공정 / 자원순환"], "tags": ["금산공장", "자가소비형 태양광", "5069kW", "공장 전력"], "summary": "금산공장의 원자재·완제품 창고 지붕에 합계 5,069kW 태양광 설비를 설치했다. 발전 전력의 공장 내 사용과 이에 따른 배출량 저감의 기대 효과를 설명한다.", "study": "공부 질문: 공장 부하 곡선과 태양광 발전 시간대가 다를 때 자가소비율·전력 품질·설비 운영을 어떻게 검토할까?"}, {"id": "hankook-633821", "url": "https://www.hankooktire.com/kr/ko/company/media-list/media-detail.633821.html", "title": "한국타이어, 겨울용 퍼포먼스 타이어 신제품 ‘윈터 아이셉트 에보4’ 국내 출시", "category": "겨울용 / 올웨더", "date": "2026-09-01", "topics": ["타이어 설계 / 성능", "컴파운드 / 재료"], "tags": ["윈터 아이셉트 에보4", "횡 방향 그루브", "다각도 사이프", "마일리지"], "summary": "겨울용 에보4의 넓은 횡 방향 홈과 다각도 사이프를 설명한다. 눈길 접지·견인, 배수와 마모 수명을 함께 개선하려는 설계 사례다.", "study": "공부 질문: 사이프의 방향·밀도와 블록 강성 변화가 눈길 견인력, 젖은 노면 제동과 마모에 어떻게 연결될까?"}, {"id": "hankook-633802", "url": "https://www.hankooktire.com/kr/ko/company/media-list/media-detail.633802.html", "title": "한국타이어, ‘2026 레드닷 디자인 어워드’ 디자인 콘셉트 부문 6관왕", "category": "미래 모빌리티 / 비공기입", "date": "2026-08-26", "topics": ["컴파운드 / 재료"], "tags": ["아이플렉스 Gen 2", "비공기입 타이어", "메디 버디", "지속가능 콘셉트"], "summary": "비공기입 타이어 아이플렉스 Gen 2와 이동형 AI 링거 등 미래 디자인 결과물을 소개한다. 연구 콘셉트의 적용 분야와 실제 양산 제품을 구분해서 읽을 자료다.", "study": "공부 질문: 콘셉트의 기능 시연에서 양산 검증으로 넘어가려면 하중·내구·제어·사용 환경 요구사항을 어떻게 구체화해야 할까?"}, {"id": "hankook-633796", "url": "https://www.hankooktire.com/kr/ko/company/media-list/media-detail.633796.html", "title": "한국타이어, ‘폴스타 4’에 ‘아이온’ 공급... 프리미엄 전기차 파트너십 확대", "category": "공급 / 계약", "date": "2026-08-25", "topics": ["전기차 / 저회전저항"], "tags": ["폴스타 4", "아이온 에보 SUV", "EV 요구 성능"], "summary": "폴스타 4에 아이온 에보 SUV를 공급하는 첫 협력을 소개한다. 차종에 맞춘 규격과 전기차용 타이어의 소음·수명·접지·회전저항 요구를 다룬다.", "study": "공부 질문: 신규 고객과의 개발에서 요구 성능 합의, 규격 승인, 품질 검증과 양산 일정을 어떻게 연결할까?"}, {"id": "hankook-633728", "url": "https://www.hankooktire.com/kr/ko/company/media-list/media-detail.633728.html", "title": "한국타이어, 쿠프라 ‘라발’에 ‘아이온’ 공급... 전동화 라인업 파트너십 강화", "category": "공급 / 계약", "date": "2026-08-13", "topics": ["전기차 / 저회전저항", "컴파운드 / 재료", "타이어 설계 / 성능"], "tags": ["아이온 에보", "아라미드 보강 벨트", "EV 형상", "이상 마모"], "summary": "쿠프라 라발용 아이온 에보의 형상과 아라미드 보강 벨트를 설명한